content:
[science_education] {
  "education_concept": "从参观走向探究，围绕滨水资源与环境议题打造“看见—操作—解释—创造”的全流程学习体验，馆校共创与社群共建联动。",
  "signature_activities": [
    {
      "name": "奇妙化学实验秀",
      "format": "现场演示 + 随机抽取观众参与",
      "spatial_requirement": "位于中庭或大台阶的开放式舞台，配备排风与给水点，满足安全防护与可视化互动。理由：兼顾可见性与安全，兼顾安全防护与氛围营造。理由：形成强记忆点与高效观演动线。"
    },
    {
      "name": "好奇玩家科学讲坛",
      "format": "主题讲座 + 实物展台互动",
      "spatial_requirement": "影视厅或多功能厅，可移动桌椅与便携实验台。理由：灵活适应不同主题与客群容量。"
    },
    {
      "name": "动手智造工坊",
      "format": "分层动手课程（入—做—评—展）",
      "spatial_requirement": "展厅内嵌入式实验室，玻璃盒子设计，配备基础电气/机械台、储料柜与工具车。理由：教学即展陈，增强体验与知识可视化。"
    },
    {
      "name": "酷玩列车展内快闪活动",
      "format": "多点位打卡与短时任务",
      "spatial_requirement": "主要展厅串联，设置移动展台与任务牌。理由：降低队列压力，提升展厅停留时长与转化。"
    },
    {
      "name": "“滨水生态观察站”",
      "format": "微型监测 + 数据可视化 + 公众共创",
      "spatial_requirement": "近滨水侧设半户外观察点与临时实验室，内置风速/水质简易监测与数据墙。理由：将滨水场域转化为活教材，强化情境学习。"
    },
    {
      "name": "星空夜宿与夜校",
      "format": "夜间观星 + 夜校微课 + 清晨潮汐观察",
      "spatial_requirement": "独立教育区夜间开放，配备可拼睡区、简易洗漱与可外连庭院/屋顶露台。理由：延长运营时段，增强家庭与研学社群粘性。"
    },
    {
      "name": "科学电影节",
      "format": "主题片展映 + 映后互动",
      "spatial_requirement": "影视厅或小型影院，同步字幕与便携展台。理由：形成品牌IP与内容联动。"
    },
    {
      "name": "“悟理剧”与“科普大篷车”",
      "format": "故事化表演 + 移动外出巡展",
      "spatial_requirement": "中庭/门厅主舞台+车载巡展平台。理由：扩大外溢影响与社区连结。"
    }
  ],
  "spatial_integration": {
    "embedded_labs": "在自然与技术展厅的核心展线布设3—4个玻璃盒子实验室（如：化学、物理、机器人与生态监测），与展项同位同语境，设置可开启的安全窗、给排水与排风点位、工具车与储料柜，并通过声光遮蔽实现分区而可视。理由：让学习与展陈同频，过程可见、可学、可评，增强现场转化与口碑传播。理由：与展品语义同步，降低理解门槛与跨空间转移成本。",
    "public_performance": "以中庭或门厅为“科学剧场”，通过大台阶与环廊组织分层观演；两侧嵌入移动展台与任务站，演出前后引导分流，形成“看—试—讲—买/报”的闭环。理由：营造仪式感与公共性，激发好奇心并引导二次消费/报名。理由：利用立体动线提升观演容量与现场秩序。"
  },
  "dedicated_education_zone": {
    "room_configuration": "建议配置：2间通用教室（20–40人）、2间实验室（物理/化学各1）、1间机器人工作室、1间STEM创客空间、1间准备与消毒间、2间小型研讨/辅导室、1间讲解员/志愿者休息与准备间。理由：满足分龄分科、分层难度的常态化课程与品牌活动承载。理由：完善教学闭环与运营保障。",
    "zoning_strategy": "位于首层并设有独立对外出入口与后勤通道，与主展厅保持可控联系；在非营业时段可单独开放，教育区与公共服务区用可控门禁与声屏障分离。理由：减少对普通观众的干扰并提高高峰时段调度效率。理由：便于夜间运营与校企合作活动的灵活组织。"
  }
}
